#!/usr/bin/env python3
"""Generate host agent files from the role manifests in roles/.

The role manifests are the only place a role's model tier, reasoning strength,
tool grant, and mutation class are written down; the prose lives once under
references/agents/. Everything under agents/ (and any other host's agent
directory) is generated from those two sources and must never be hand-edited.

The rule that makes this worth having: a capability the host cannot express is
never silently dropped. It is written into an "Enforcement" section of the
generated file, marked unenforced, and reported by --check. A brief that claims
host-enforced isolation it does not have is worse than one that admits the
instruction is all there is.

    render_agents.py --host claude-code --out agents
    render_agents.py --host claude-code --out agents --check
"""

import argparse
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from jsonschema_mini import Validator  # noqa: E402
from return_shape import skeleton  # noqa: E402

ROOT = Path(__file__).resolve().parent.parent
SCHEMAS = ROOT / "schemas"

# A quality finding needs a failure scenario, which the schema cannot mark
# required for only one of the two roles that share it. Show it anyway.
EXTRA_FIELDS = {"quality-validator": {"failure_scenario"}}


def return_skeleton(role):
    return skeleton(
        SCHEMAS / role["returns"],
        extra=EXTRA_FIELDS.get(role["role"], ()),
        pin={"role": role["role"]},
    )


BANNER = (
    "GENERATED by scripts/render_agents.py from roles/{role_file} and "
    "hosts/{host}.json. Do not edit by hand; edit the role manifest and "
    "regenerate."
)


def load_roles():
    validator = Validator(SCHEMAS / "agent-role.schema.json")
    roles = []
    for path in sorted((ROOT / "roles").glob("*.json")):
        role = json.loads(path.read_text(encoding="utf-8"))
        errors = validator.validate(role)
        if "run-commands" in role.get("tools", {}).get("allow", []):
            if not role["tools"].get("shell_purpose"):
                errors.append(
                    "$.tools.shell_purpose: required when the grant includes run-commands"
                )
        if errors:
            raise SystemExit(
                "roles/%s is not schema-conformant:\n  %s" % (path.name, "\n  ".join(errors))
            )
        roles.append((path.name, role))
    return roles


def load_host(name):
    path = ROOT / "hosts" / ("%s.json" % name)
    if not path.exists():
        raise SystemExit("no host manifest at %s" % path)
    host = json.loads(path.read_text(encoding="utf-8"))
    errors = Validator(SCHEMAS / "host-capability.schema.json").validate(host)
    for key, cap in host.get("capabilities", {}).items():
        if cap.get("supported") and not cap.get("field"):
            errors.append("$.capabilities.%s.field: required when supported" % key)
    if host["capabilities"]["reasoning_effort"]["supported"] and not host.get("effort_map"):
        errors.append("$.effort_map: required when reasoning_effort is supported")
    if errors:
        raise SystemExit(
            "hosts/%s.json is not schema-conformant:\n  %s" % (name, "\n  ".join(errors))
        )
    return host


def format_allow_list(allow):
    """The grant, in prose, naming the empty case rather than rendering blank.

    `", ".join([])` is the empty string, which reads as `Allowed: .` — text a
    model cannot act on. An empty mapped allow list is a real state on a host
    that enforces no allowlist, so it gets words instead of a blank.

    This is prose only. An empty allowlist *field* is not a rendering problem
    to word around; see render_markdown_yaml.
    """
    return ", ".join(allow) if allow else "no host-enforced tools"


def toml_multiline(text):
    '''Escape a value for the body of a TOML multi-line basic string.

    `developer_instructions` is emitted inside """...""", which processes
    backslash escapes and terminates at the first """. The plugin root lands
    in that body and is supplied by whoever runs the installer, so unescaped
    input does not merely look wrong: a path containing a backslash is
    silently rewritten (\\t parses as a tab, and the agent then cannot find
    its role prose), and one containing """ closes the string early and turns
    the remaining instructions into TOML statements.

    Only what actually breaks the delimiter is escaped — backslashes, and
    runs of three or more quotes. A lone or doubled quote is legal inside
    """ and is left alone, so the JSON return skeleton stays readable and
    today's generated files keep their exact bytes. Backslashes are escaped
    first so the quote escapes are not escaped again.
    '''
    text = text.replace("\\", "\\\\")
    return re.sub(r'"{3,}', lambda m: '\\"' * len(m.group()), text)


def toml_basic(text):
    """Escape a value for a single-line TOML basic string."""
    return text.replace("\\", "\\\\").replace('"', '\\"')


def yaml_double_quoted(text):
    """Quote a value for a YAML double-quoted scalar.

    Every other frontmatter value this renderer writes is a bare scalar drawn
    from a constrained vocabulary - a model alias, a tool name, an id matching
    a pattern. `initialPrompt` is the first free prose to reach the
    frontmatter, and prose contains the two characters that end a plain scalar:
    a colon-space starts a mapping, a leading `#` starts a comment. Quoting is
    not tidiness here - an unquoted prompt containing ": " makes the whole
    frontmatter block parse as something else, and the agent silently launches
    without the startup check it exists to carry.
    """
    escaped = text.replace("\\", "\\\\").replace('"', '\\"')
    return '"%s"' % escaped.replace("\n", "\\n")


def is_dispatched(role):
    """Whether something else starts this agent.

    Everything in this architecture is dispatched except root, which runs as
    the main thread. The distinction is load-bearing wherever delegation is
    reasoned about: a dispatched agent that delegates needs NESTED delegation,
    a main-thread one needs only delegation. Reading this wrong in either
    direction ships a false claim - it would either block root on a host that
    can carry it, or let a dispatched agent rest on nesting nobody sourced.
    """
    return role["kind"] != "root"


def role_targets_host(role, host_name):
    """Whether this role may be generated for this host at all.

    Derived from adapters/<host>/agent-interface.json rather than declared on
    the role, so it tracks what the host was last measured to do. A DISPATCHED
    role that delegates needs NESTED delegation - it would be a spawned agent
    spawning - and a host whose nesting is unsourced may not carry it.
    Generating one anyway would ship an agent that cannot do the one thing it
    exists for, on the strength of an assumption. Root needs only plain
    delegation, because nothing spawned root.

    Returns (True, None) or (False, reason).
    """
    if "delegate" not in role["tools"]["allow"]:
        return True, None

    interface_path = ROOT / "adapters" / host_name / "agent-interface.json"
    if not interface_path.is_file():
        return False, (
            "no agent-interface.json for %s, so whether it can nest "
            "delegation is unknown" % host_name
        )
    try:
        interface = json.loads(interface_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return False, ("%s's agent-interface.json will not load (%s)" % (host_name, exc))

    delegation = interface.get("delegation", {})
    claim = delegation.get("nested", {}) if is_dispatched(role) else delegation
    what = "nested delegation" if is_dispatched(role) else "delegation"

    level = (claim.get("provenance") or {}).get("level")
    if level in (None, "unsourced"):
        return False, (
            "%s is unsourced on %s; a delegating role may not be "
            "built against an assumption" % (what, host_name)
        )
    if not claim.get("supported"):
        return False, "%s does not support %s" % (host_name, what)
    return True, None


def delegation_scope(role, host):
    """How this host handles "you may dispatch only these types", for this role.

    Returns (names, enforced, note): the tool names the delegate intent must be
    written as, whether the restriction actually binds for THIS role, and the
    sentence that goes in the Enforcement section - or None where there is
    nothing to say.

    The asymmetry is the whole reason this is a function. On a host whose scope
    binds only for the main thread, the very same syntax is a guarantee in
    root's file and a decoration in the orchestrator's. Deriving both from the
    manifest keeps the renderer from hardcoding which host that is, which it
    used to.
    """
    tool_names = host["tool_map"].get("delegate") or []
    if "delegate" not in role["tools"]["allow"]:
        return tool_names, False, None

    scope = (host.get("main_thread") or {}).get("delegate_scope") or {}
    declared = (role.get("launch") or {}).get("delegates_to")
    main_thread_only = bool(scope.get("main_thread_only"))

    if not tool_names:
        # An unmapped intent is not the same as a missing capability: codex
        # maps no tool name for reading either, and plainly reads. So this is
        # not a reason to refuse to build - but a declared dispatch scope on a
        # host where this repository cannot even name the dispatching tool is
        # the weakest form the restriction takes, and saying nothing would
        # leave root's file quietly silent about its only real boundary.
        if declared:
            return (
                tool_names,
                False,
                (
                    "You may dispatch only: %s. This host maps no tool name to "
                    "delegation in hosts/%s.json, so neither the grant nor the "
                    "scope is written anywhere the host reads - both are "
                    "instructions to you and nothing else." % (", ".join(declared), host["host"])
                ),
            )
        return tool_names, False, None

    if not declared:
        # Nothing to scope TO. The only thing worth saying is for a dispatched
        # delegator on a host that has the syntax but ignores it there - the
        # grant would otherwise imply a restriction the host does not apply.
        if scope.get("supported") and main_thread_only and is_dispatched(role):
            return (
                tool_names,
                False,
                (
                    "Which agents you may dispatch is **not enforced**. This "
                    "host's %s restriction binds only for an agent running as the "
                    "main thread, and you are dispatched, so the type list is "
                    "ignored for you. Your grant is delegation to anything the "
                    "session offers; dispatching only the worker roles is your "
                    "obligation, not the host's guarantee."
                    % scope["template"].format(tool=tool_names[0], types="type")
                ),
            )
        return tool_names, False, None

    if not scope.get("supported"):
        return (
            tool_names,
            False,
            (
                "You may dispatch only: %s. This host cannot express that "
                "restriction in an agent definition, so it is an instruction and "
                "nothing refuses a different dispatch." % ", ".join(declared)
            ),
        )

    types = scope.get("separator", ", ").join(
        (scope.get("type_template") or "{id}").format(plugin=plugin_name(host["host"]), id=name)
        for name in declared
    )
    scoped = [scope["template"].format(tool=name, types=types) for name in tool_names]

    if main_thread_only and is_dispatched(role):
        # Declaring a scope on an agent the host will not scope. Nothing in
        # this repository does it, but the honest rendering is the bare grant
        # plus the reason, not a syntax the host discards.
        return (
            tool_names,
            False,
            (
                "You declare a dispatch scope of %s, but this host applies that "
                "restriction only to a main-thread agent and you are dispatched. "
                "The grant written above is unscoped." % ", ".join(declared)
            ),
        )

    return (
        scoped,
        True,
        (
            "**Dispatch scope is enforced.** Your grant is written as `%s`, and "
            "this host resolves it: an attempt to dispatch anything else has no "
            "tool to make it with.%s"
            % (
                ", ".join(scoped),
                " This is the one guarantee that depends on how you were started - "
                "it binds because you run as the main thread, and would be ignored "
                "if this same file were dispatched as a subagent."
                if main_thread_only
                else "",
            )
        ),
    )


def both_positions(host_name, source):
    """Where a layout source sits here, and where the build puts it, in order.

    Several things in this repository run from two trees: the repository, where
    a file sits at its source path, and an installed bundle, where it sits
    wherever that host's layout placed it. Rather than each caller learning
    both paths, they ask the layout - so a host that nests its plugin under a
    subdirectory is handled by its own layout entry and not by a branch in
    shared code.

    Deliberately NOT used by hooks/root_write_guard.py, which has the same
    problem and solves it with two hardcoded paths. That guard is looking for
    scripts/ in the first place, so it cannot import a helper that lives there.
    """
    adapter = ROOT / "adapters" / host_name
    # The source position resolves the way build_adapter.resolve_source does -
    # adapter directory first, repository root second - because that is what
    # decides which file the build actually picked up. Reading it differently
    # here would mean checking a file the bundle was not made from.
    positions = [p for p in (adapter / source.rstrip("/"), ROOT / source.rstrip("/")) if p.exists()]
    layout = adapter / "layout.json"
    if layout.is_file():
        place = json.loads(layout.read_text(encoding="utf-8")).get("place", {})
        for declared, destination in place.items():
            if declared.rstrip("/") == source.rstrip("/"):
                positions.append(ROOT / destination.rstrip("/"))
    return positions or [ROOT / source.rstrip("/")]


def plugin_name(host_name):
    """The name the host loads this plugin's agents under.

    Read from that host's manifest template rather than hardcoded, because it
    is the same string in two places otherwise and a rename would leave root's
    type list pointing at agents that no longer answer to those names.

    Per host since ADR 0001 step 3 moved the manifest into the adapter, which
    is also more correct than the single root copy it replaced: nothing says
    two hosts must name the same plugin the same way, and Codex's manifest is
    already a separate file.
    """
    for candidate in both_positions(host_name, "adapters/%s/manifest.template.json" % host_name):
        if candidate.is_file():
            return json.loads(candidate.read_text(encoding="utf-8"))["name"]
    raise SystemExit(
        "cannot find %s's plugin manifest; looked at %s. The name this host "
        "loads the plugin's agents under is not guessable: a scoped dispatch "
        "grant written against a wrong name matches no agent at all, and the "
        "frontmatter still looks correct."
        % (
            host_name,
            ", ".join(
                str(c)
                for c in both_positions(host_name, "adapters/%s/manifest.template.json" % host_name)
            ),
        )
    )


def resolve_tools(role, host):
    """Map portable intents to host tool names, collecting what cannot map."""
    tool_map = host["tool_map"]
    scoped_delegate, _enforced, _note = delegation_scope(role, host)
    allow, deny, unmappable = [], [], []
    for intent in role["tools"]["allow"]:
        names = scoped_delegate if intent == "delegate" else tool_map.get(intent)
        if not names:
            unmappable.append(intent)
            continue
        for name in names:
            if name not in allow:
                allow.append(name)
    for intent in role["tools"]["deny"]:
        for name in tool_map.get(intent, []):
            if name not in deny and name not in allow:
                deny.append(name)
    return allow, deny, unmappable


def enforced_prohibitions(role, host):
    """Which of this role's must_not items the host makes impossible, not merely
    forbidden.

    Two sources, deliberately kept apart. A prohibition the renderer can DERIVE
    from tool_map plus the role's own grant cannot drift: change the grant and
    the claim changes with it. One the host must DECLARE can drift, so it costs
    a `verified` note in the manifest and is only used where derivation is
    impossible -- `ask-owner` maps to no portable intent at all, so nothing in
    tool_map could ever imply it.

    Understating enforcement is its own failure in a file whose purpose is to
    state enforcement accurately, which is why this exists alongside
    disclosures() rather than inside it.
    """
    caps = host["capabilities"]
    forbidden = set(role["must_not"])
    found = {}

    for name, entry in (host.get("enforced_prohibitions") or {}).items():
        if name in forbidden:
            found[name] = entry["verified"]

    # Derived: spawning is host-blocked when the allowlist is enforced and the
    # delegate intent never reaches the written grant.
    if "spawn-agents" in forbidden and caps["tool_allowlist"]["supported"]:
        delegate = host["tool_map"].get("delegate") or []
        allow, _deny, _unmappable = resolve_tools(role, host)
        if delegate and not any(name in allow for name in delegate):
            found.setdefault(
                "spawn-agents",
                "%s is absent from the `%s` grant this agent is written with, "
                "and this host enforces that grant, so the tool needed to spawn "
                "cannot be called." % (", ".join(delegate), caps["tool_allowlist"]["field"]),
            )
    return found


def disclosures(role, host, unmappable):
    """Every guarantee this host will not enforce, stated plainly."""
    caps = host["capabilities"]
    out = []
    if not caps["tool_allowlist"]["supported"]:
        out.append(
            "Tool grant is **not enforced** on this host: %s has no per-agent "
            "tool allowlist, so the grant stated above is an instruction only." % host["host"]
        )
    if unmappable:
        out.append(
            "These portable tool intents have no mapping on this host and are "
            "instructions only: %s." % ", ".join(sorted(unmappable))
        )
    if role["mutation"] == "read-only" and not caps["read_only_enforced"]["supported"]:
        out.append(
            "Read-only is **not enforced** on this host. Do not describe this "
            "agent as isolated; it is a read-only instruction."
        )
    if role["mutation"] == "write-scoped":
        out.append(
            "Write scope is **never** host-enforced anywhere: no host limits "
            "edits to a brief's write paths. The boundary holds because the "
            "agent honours it and root reviews the diff against it."
        )
        if host["host"] == "codex":
            out.append(
                "Codex does not document worker identity in PreToolUse, so its "
                "root-versus-worker write separation is not hook-enforced; "
                "root must review the materialized worker diff."
            )
    if not caps["reasoning_effort"]["supported"]:
        out.append(
            "Reasoning strength is not settable on this host. Record effort as "
            "'not settable on this host' rather than naming a level nothing "
            "applied."
        )
    else:
        mapped = host["effort_map"]
        folded = sorted(
            {
                lvl
                for lvl in ([role["reasoning"]["default"]] + role["reasoning"]["escalation"])
                if mapped.get(lvl) != lvl
            }
        )
        if folded:
            out.append(
                "This host's effort scale is coarser than the manifest's: %s."
                % "; ".join("%s is applied as %s" % (lvl, mapped[lvl]) for lvl in folded)
            )
    if not caps["scoped_hooks"]["supported"]:
        out.append(
            "Per-agent hooks are unavailable on this host, so the prohibitions "
            "stated above rely on session-wide hooks or on the agent's own "
            "compliance."
        )
    # An agent that delegates can be told WHICH types to delegate to, but on a
    # host where that restriction binds only for the main thread it does not
    # bind for a dispatched one - its type list is ignored. Root gets the
    # enforced version of this and the orchestrator does not, which is an
    # asymmetry worth stating rather than letting the grant imply otherwise.
    # Which side of it a role lands on is read from the manifest; this used to
    # name claude-code in an `if`, which made the claim true only by accident.
    _names, enforced, note = delegation_scope(role, host)
    if note and not enforced:
        out.append(note)

    if role["kind"] == "root" and not main_thread_startup(host):
        out.append(
            "This host does not auto-submit a startup prompt, so your startup "
            "check runs only because you run it. Nothing will stop a session "
            "that skips it, which is exactly the failure the check exists to "
            "catch - treat it as the first thing you do, not the first thing "
            "you can defer."
        )
    return out


def main_thread_startup(host):
    """The field this host auto-submits a main-thread agent's first prompt in.

    None where it has none, or declares none. A host that says nothing about it
    is treated as having none: the fallback is an instruction root must follow
    rather than a prompt the host submits, which is the safe direction to be
    wrong in.
    """
    block = (host.get("main_thread") or {}).get("initial_prompt") or {}
    return block.get("field") if block.get("supported") else None


def guarantees(role, host):
    """What this host enforces that is NOT a prohibition from must_not.

    Kept apart from enforced_prohibitions() because the shapes differ: that one
    answers "which of this role's declared prohibitions are impossible to
    violate here", and root's dispatch scope is not a prohibition it declared -
    it is a positive restriction the host applies to the grant itself.
    """
    _names, enforced, note = delegation_scope(role, host)
    return [note] if note and enforced else []


def render_markdown_yaml(role, host, role_file):
    caps = host["capabilities"]
    prefix = host.get("root_placeholder", "<skill_root>")
    allow, deny, unmappable = resolve_tools(role, host)
    lines = ["---", "name: %s" % role["id"], "description: %s" % role["description"]]
    if caps.get("subagent_flag", {}).get("supported"):
        field = (
            caps["subagent_flag"]["main_thread_field"]
            if (role.get("launch") or {}).get("main_thread")
            else caps["subagent_flag"]["dispatched_field"]
        )
        lines.append("%s: true" % field)

    model = host["model_map"][role["model"]["default"]]
    effort = None
    if caps["reasoning_effort"]["supported"]:
        effort = host["effort_map"][role["reasoning"]["default"]]
    if caps["reasoning_effort"].get("field") == caps["explicit_model"].get("field"):
        # Cursor encodes effort inside the model string rather than beside it.
        lines.append("%s: %s[effort=%s]" % (caps["explicit_model"]["field"], model, effort))
    else:
        lines.append("%s: %s" % (caps["explicit_model"]["field"], model))
        if effort is not None:
            lines.append("%s: %s" % (caps["reasoning_effort"]["field"], effort))

    if caps["tool_allowlist"]["supported"]:
        if not allow:
            # Neither available option is safe, so neither is taken. Emitting
            # the field empty is a malformed grant; omitting it is worse,
            # because every host that has an allowlist treats the absent field
            # as "inherit everything" — hosts/claude-code.json records exactly
            # that for `tools`, and read_only_enforced points at the same
            # field, so an omitted line also drops read-only enforcement. An
            # empty grant would silently render as a full one.
            #
            # schemas/agent-role.schema.json already names the right answer:
            # an intent a host cannot express "is a rendering error, not a
            # silent drop". So it is raised here rather than worded around.
            raise SystemExit(
                "hosts/%s.json enforces a tool allowlist (%s), but role %r "
                "maps to no host tool%s.\nOmitting the field would grant every "
                "tool on this host and emitting it empty is malformed, so this "
                "is a rendering error: map the intent in tool_map, or declare "
                "capabilities.tool_allowlist.supported = false."
                % (
                    host["host"],
                    caps["tool_allowlist"]["field"],
                    role["id"],
                    " (unmappable: %s)" % ", ".join(sorted(unmappable)) if unmappable else "",
                )
            )
        lines.append("%s: %s" % (caps["tool_allowlist"]["field"], ", ".join(allow)))
    if caps["tool_denylist"]["supported"] and deny:
        lines.append("%s: %s" % (caps["tool_denylist"]["field"], ", ".join(deny)))
    if (
        role["mutation"] == "read-only"
        and caps["read_only_enforced"]["supported"]
        and caps["read_only_enforced"]["field"] not in (caps["tool_allowlist"].get("field"), None)
    ):
        lines.append("%s: true" % caps["read_only_enforced"]["field"])
    startup_field = main_thread_startup(host)
    startup = (role.get("launch") or {}).get("initial_prompt")
    if startup and startup_field:
        lines.append("%s: %s" % (startup_field, yaml_double_quoted(startup)))
    lines.append("---")

    lines += [
        "",
        "<!-- %s -->" % BANNER.format(role_file=role_file, host=host["host"]),
        "",
        "# Role — %s" % role["role"],
        "",
        "Read `%s/%s` before doing anything. It is the canonical "
        "definition of this role and it governs you; this file carries "
        "only the host frontmatter and the disclosures below." % (prefix, role["prose"]),
        "",
    ]
    if role["returns"] == "none":
        # Root answers to the operator in prose. Emitting an empty contract
        # here, or a skeleton of nothing, would invent a return for an agent
        # that has nobody to return to.
        lines += [
            "You return nothing to anybody. The record of a run is the "
            "ledger, the envelopes and the Git history, not a summary "
            "you wrote.",
            "",
        ]
    else:
        lines += [
            "Return exactly one fenced `json` block in this shape, and "
            "nothing else. Root validates it mechanically before reading "
            "it; a malformed return is sent back once.",
            "",
            "```json",
            return_skeleton(role),
            "```",
            "",
            "Placeholders show the type; `a|b` means pick one. The full "
            "contract, including the optional fields, is "
            "`%s/schemas/%s`." % (prefix, role["returns"]),
            "",
        ]

    startup = (role.get("launch") or {}).get("initial_prompt")
    if startup:
        lines += ["## Startup", "", startup, ""]

    lines += ["## Grant", "", "Capability class: **%s**." % role["mutation"], ""]
    lines.append("Allowed: %s." % format_allow_list(allow))
    if deny:
        lines.append("Denied: %s." % ", ".join(deny))
    if role["tools"].get("shell_purpose"):
        lines += [
            "",
            "Shell purpose — the only reason a shell exists for you: %s"
            % role["tools"]["shell_purpose"],
        ]
    lines += ["", "## Never", "", "You must never: %s." % ", ".join(sorted(role["must_not"])), ""]

    notes = disclosures(role, host, unmappable)
    enforced = enforced_prohibitions(role, host)
    held = guarantees(role, host)
    lines += ["## Enforcement", ""]
    if notes:
        lines.append("What this host does *not* enforce for you:")
        lines.append("")
        lines += ["- %s" % note for note in notes]
        lines.append("")
    elif not enforced and not held:
        lines.append("Every declared capability is enforced by the host itself.")
        lines.append("")
    if enforced or held:
        lines.append("What this host **does** enforce, so it is not left to your compliance:")
        lines.append("")
        lines += ["- **%s** — %s" % (name, why) for name, why in sorted(enforced.items())]
        lines += ["- %s" % note for note in held]
        lines.append("")
    return "\n".join(lines)


def render_toml(role, host, role_file):
    caps = host["capabilities"]
    prefix = host.get("root_placeholder", "<skill_root>")
    allow, deny, unmappable = resolve_tools(role, host)
    notes = disclosures(role, host, unmappable)
    body = [
        "Read %s/%s before doing anything. It is the canonical "
        "definition of this role and it governs you." % (prefix, role["prose"]),
        "",
    ]
    if role["returns"] == "none":
        body += [
            "You return nothing to anybody. The record of a run is the "
            "ledger, the envelopes and the Git history, not a summary you "
            "wrote.",
            "",
        ]
    else:
        body += [
            "Return exactly one fenced json block in this shape, and "
            "nothing else. Placeholders show the type; a|b means pick "
            "one. The full contract is %s/schemas/%s." % (prefix, role["returns"]),
            "",
            return_skeleton(role),
            "",
        ]
    startup = (role.get("launch") or {}).get("initial_prompt")
    if startup:
        body += ["Startup: %s" % startup, ""]
    body.append("Capability class: %s. Allowed: %s." % (role["mutation"], format_allow_list(allow)))
    if deny:
        body.append("Denied: %s." % ", ".join(deny))
    if role["tools"].get("shell_purpose"):
        body.append("Shell purpose: %s" % role["tools"]["shell_purpose"])
    body.append("You must never: %s." % ", ".join(sorted(role["must_not"])))
    if notes:
        body.append("")
        body.append("Not enforced by this host:")
        body += ["- %s" % note.replace("**", "") for note in notes]
    enforced = enforced_prohibitions(role, host)
    held = guarantees(role, host)
    if enforced or held:
        body.append("")
        body.append("Enforced by this host, not left to your compliance:")
        body += [
            "- %s: %s" % (name, why.replace("**", "")) for name, why in sorted(enforced.items())
        ]
        body += ["- %s" % note.replace("**", "") for note in held]

    lines = [
        "# %s" % BANNER.format(role_file=role_file, host=host["host"]),
        'name = "%s"' % toml_basic(role["id"]),
        'description = "%s"' % toml_basic(role["description"].replace('"', "'")),
        '%s = "%s"'
        % (
            caps["explicit_model"]["field"],
            toml_basic(host["model_map"][role["model"]["default"]]),
        ),
    ]
    if caps["reasoning_effort"]["supported"]:
        lines.append(
            '%s = "%s"'
            % (
                caps["reasoning_effort"]["field"],
                toml_basic(host["effort_map"][role["reasoning"]["default"]]),
            )
        )
    if role["mutation"] == "read-only" and caps["read_only_enforced"]["supported"]:
        lines.append('%s = "read-only"' % caps["read_only_enforced"]["field"])
    startup_field = main_thread_startup(host)
    if startup and startup_field:
        lines.append('%s = "%s"' % (startup_field, toml_basic(startup)))
    lines.append('developer_instructions = """')
    # Everything above is generated from repo-controlled manifests. `body`
    # is not: it carries the plugin root the installer was given, so it is
    # the one part that has to survive an arbitrary filesystem path.
    lines += [toml_multiline(line) for line in body]
    lines.append('"""')
    return "\n".join(lines) + "\n"


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", default="claude-code")
    parser.add_argument(
        "--out",
        default=None,
        help="output directory; defaults to the host manifest's "
        "agent_dir, resolved inside the plugin",
    )
    parser.add_argument(
        "--root-placeholder",
        default=None,
        help="path used when generated instructions refer to the "
        "plugin root (installers should pass an absolute path)",
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="regenerate in memory and fail if what is on disk differs, instead of writing",
    )
    args = parser.parse_args(argv)

    host = load_host(args.host)
    if args.root_placeholder is not None:
        host = dict(host)
        host["root_placeholder"] = args.root_placeholder
    out_dir = Path(args.out) if args.out else ROOT / host["bundled_dir"]
    extension = ".toml" if host["format"] == "toml" else ".md"
    render = render_toml if host["format"] == "toml" else render_markdown_yaml

    drifted, written, skipped, stale = [], [], [], []
    for role_file, role in load_roles():
        target = out_dir / (role["id"] + extension)
        allowed, reason = role_targets_host(role, args.host)
        if not allowed:
            skipped.append((role["id"], reason))
            # A file left behind from when the role DID target this host is
            # worse than a missing one: it looks generated and current.
            if target.exists():
                if args.check:
                    stale.append((str(target), reason))
                else:
                    target.unlink()
            continue
        content = render(role, host, role_file)
        if args.check:
            current = target.read_text(encoding="utf-8") if target.exists() else None
            if current != content:
                drifted.append(str(target))
            continue
        out_dir.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        written.append(str(target))

    if args.check:
        if drifted or stale:
            print("out of sync with roles/ and hosts/%s.json:" % args.host, file=sys.stderr)
            for path in drifted:
                print("  %s" % path, file=sys.stderr)
            for path, reason in stale:
                print("  %s should not exist: %s" % (path, reason), file=sys.stderr)
            print("run: render_agents.py --host %s" % args.host, file=sys.stderr)
            return 1
        print(
            "in sync: %s agent files match roles/ and hosts/%s.json"
            % (len(load_roles()) - len(skipped), args.host)
        )
        for role_id, reason in skipped:
            print("  not built for this host: %s - %s" % (role_id, reason))
        return 0

    for path in written:
        print("wrote %s" % path)
    for role_id, reason in skipped:
        print("skipped %s: %s" % (role_id, reason))
    return 0


if __name__ == "__main__":
    sys.exit(main())
